        $req = ApiRequest::post('/process-instances/' . HttpTransport::seg((string) $id) . '/updates/' . HttpTransport::seg((string) $name));
        if ($body !== null) {
            $req->body($body);
        }
        return $this->calls->model($req, $options, Model\InstanceUpdateResult::class);
    }
}
